create table xxcus.xxcmp_attachment_rules (
    attachment_rule_id    number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    entity_name           varchar2(60 byte) not null enable,
    category_code         varchar2(30 byte) not null enable,
    jurisdiction          varchar2(30 byte),
    entity_type           varchar2(30 byte),
    mandatory_flag        varchar2(1 byte) default 'Y' not null enable,
    priority              number default 100 not null enable,
    enabled_flag          varchar2(1 byte) default 'Y' not null enable,
    approval_status       varchar2(20 byte) default 'DRAFT' not null enable,
    approved_by           varchar2(255 byte),
    approved_date         timestamp(6),
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxcmp_attachment_rules
    add constraint xxcmp_attachment_rules_ck1
        check ( mandatory_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_attachment_rules
    add constraint xxcmp_attachment_rules_ck2
        check ( enabled_flag in ( 'Y', 'N' ) ) enable;

alter table xxcus.xxcmp_attachment_rules
    add constraint xxcmp_attachment_rules_ck3
        check ( approval_status in ( 'DRAFT', 'PENDING_APPROVAL', 'APPROVED', 'REJECTED' ) ) enable;

alter table xxcus.xxcmp_attachment_rules
    add constraint xxcmp_attachment_rules_pk primary key ( attachment_rule_id )
        using index enable;


